const renderProducts=()=>{const host=one("#products");if(!host)return;host.innerHTML=products.map((p,index)=>`<div class="product"><i style="background:${p.color}">${p.emoji}</i><span><b>${p.name}</b><small>${p.sku} · ${p.price.toFixed(2)}</small></span><em class="${p.stock?'low':'out'}">${p.stock?p.stock+' '+tr("left"):tr("Out")}</em><button class="remove-item" data-remove-product="${index}" aria-label="${tr("Remove")} ${p.name}">×</button></div>`).join("");all("[data-remove-product]",host).forEach(button=>button.onclick=()=>{const item=products[Number(button.dataset.removeProduct)];if(confirm(tr("Remove this product from the prototype catalog?"))){products.splice(Number(button.dataset.removeProduct),1);saveProducts();renderProducts()}})};
