const clearDashboardView=()=>{activeView="";state.remove("active-view");history.replaceState(null,"",location.pathname+location.search);all('[data-view]').forEach(button=>{button.classList.remove("active");button.setAttribute("aria-pressed","false")});one("#mobileSettings")?.setAttribute("aria-pressed","false");one(".section-title").hidden=true;viewHost.innerHTML="";viewHost.hidden=true};
const selectView=view=>{if(!businessViews.has(view))return;if(activeView===view){clearDashboardView();closeMenu();return}activeView=view;state.set("active-view",view);history.replaceState(null,"","#"+view.toLowerCase());one("#mobileSettings")?.setAttribute("aria-pressed",String(view==="Settings"));if(view==="Notifications"){state.set("notifications-read",true);const unread=one(".bell i");if(unread)unread.hidden=true}all('[data-view]').forEach(button=>{const selected=button.dataset.view===view;button.classList.toggle("active",selected);button.setAttribute("aria-pressed",selected?"true":"false")});if(businessViews.has(view))renderDashboardView(view);closeMenu()};
all('[data-view]').forEach(b=>b.onclick=()=>selectView(b.dataset.view));
