const drawSparklines=()=>{all(".sparkline").forEach(canvas=>{const values=canvas.dataset.points.split(",").map(Number),ctx=canvas.getContext("2d"),w=canvas.width,h=canvas.height,pad=5,min=Math.min(...values),max=Math.max(...values);ctx.clearRect(0,0,w,h);ctx.strokeStyle=canvas.dataset.color||"#2b6b5c";ctx.lineWidth=3;ctx.lineJoin="round";ctx.beginPath();values.forEach((v,i)=>{const x=pad+i*(w-pad*2)/(values.length-1),y=h-pad-(v-min)/(max-min||1)*(h-pad*2);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})};
function renderDashboardView(view="Overview"){one(".section-title").hidden=false;viewHost.hidden=false;viewHost.innerHTML=view==="Overview"?overviewTemplate():(details[view]?.()||overviewTemplate());all("[data-open-view]",viewHost).forEach(b=>b.onclick=()=>selectView(b.dataset.openView));all("[data-back]",viewHost).forEach(b=>b.onclick=()=>selectView("Overview"));all("[data-add]",viewHost).forEach(b=>b.onclick=openModal);renderProducts();localize(viewHost);drawSparklines();if(view==="Settings")wireBrandSettings();if(view==="Support")wireSupportRequest();if(view==="Accounting"){wireAccounting();renderPartyRecords()}wirePartyActions();wireTooltips();viewHost.scrollIntoView({behavior:"smooth",block:"start"})}
