const applyBrand=()=>{one("#tenantName").textContent=brandState.name;one("#tenantMotto").textContent=brandState.motto;renderLogo(one("#tenantLogo"))};
function wireBrandSettings(){const form=one("#brandSettingsForm"),name=one("#brandNameInput"),motto=one("#brandMottoInput"),file=one("#brandLogoFile"),status=one("#brandSaveStatus");name.value=brandState.name;motto.value=brandState.motto;one("#settingsNamePreview").textContent=brandState.name;one("#settingsMottoPreview").textContent=brandState.motto;renderLogo(one("#settingsLogoPreview"));const preview=()=>{one("#settingsNamePreview").textContent=name.value||tr("Your business");one("#settingsMottoPreview").textContent=motto.value||tr("Your motto")};name.oninput=preview;motto.oninput=preview;file.onchange=()=>{const selected=file.files[0];if(!selected)return;const reader=new FileReader();reader.onload=()=>{pendingLogo=reader.result;renderLogo(one("#settingsLogoPreview"),pendingLogo)};reader.readAsDataURL(selected)};form.onsubmit=e=>{e.preventDefault();brandState={name:name.value.trim()||defaultBrand.name,motto:motto.value.trim()||defaultBrand.motto,logo:pendingLogo};const saved=state.set("brand",brandState);applyBrand();status.textContent=saved?tr("Business identity saved."):tr("Unable to save in this browser.");}}
function wireSupportRequest(){const email=one("#supportEmail"),password=one("#supportPassword"),ack=one("#supportAcknowledge"),start=one("#startSupportRequest"),status=one("#supportStatus");let acknowledged=false;const update=()=>{const ready=email.validity.valid&&password.value.length>0&&acknowledged;start.disabled=!ready;ack.classList.toggle("acknowledged",acknowledged);ack.setAttribute("aria-pressed",acknowledged);ack.textContent=tr(acknowledged?"Acknowledged":"Acknowledge")};email.addEventListener("input",update);password.addEventListener("input",update);ack.onclick=()=>{acknowledged=!acknowledged;update()};start.onclick=()=>{if(start.disabled)return;password.value="";acknowledged=false;update();status.textContent=tr("Support request prepared. Your password was not included or stored.")}}
