const navHelp={Overview:"Business overview",Orders:"Review and fulfill orders",Products:"Manage your product catalog",Inventory:"Track stock and restocking",Marketplace:"Find SMB suppliers and partners",Logistics:"Manage shipments and couriers",Accounting:"Review income, expenses, and tax",Reports:"Open business reports"};
