function wireTooltips(){all("[data-tooltip]").forEach(el=>{if(el.dataset.tooltipReady)return;el.dataset.tooltipReady="true";const show=()=>{tooltip.textContent=el.dataset.tooltip;tooltip.hidden=false;const r=el.getBoundingClientRect(),w=tooltip.offsetWidth;tooltip.style.left=Math.max(8,Math.min(innerWidth-w-8,r.left+r.width/2-w/2))+"px";tooltip.style.top=Math.min(innerHeight-tooltip.offsetHeight-8,r.bottom+8)+"px"};const hide=()=>tooltip.hidden=true;el.addEventListener("mouseenter",show);el.addEventListener("mouseleave",hide);el.addEventListener("focus",show);el.addEventListener("blur",hide)})}
const partyModal=one("#partyModal"),partyForm=one("#partyForm"),partyType=one("#partyType"),partyNumber=one("#partyNumber"),billingCycle=one("#billingCycle"),customDueWrap=one("#customDueWrap");
