function renderPartyRecords(){const host=one("#partyList");if(!host)return;host.innerHTML=partyRecords.length?partyRecords.map((record,index)=>`<div><span><b>${record.number} · ${record.name}</b><small>${tr(record.type==="provider"?"Provider":"Client")} · ${tr(record.cycle)} · ${record.tax}% ${tr("tax")} · ${money(Number(record.amount)||0)}</small></span><em>${tr(record.type==="provider"?"Payable":"Receivable")}</em><button class="remove-record" data-remove-party="${index}" aria-label="${tr("Remove")} ${record.name}">×</button></div>`).join(""):`<p class="empty-records">${tr("No business records. Add a client or provider to begin.")}</p>`;all("[data-remove-party]",host).forEach(button=>button.onclick=()=>{const record=partyRecords[Number(button.dataset.removeParty)];if(confirm(tr("Remove this business record?")+" "+record.number)){partyRecords.splice(Number(button.dataset.removeParty),1);savePartyRecords();renderPartyRecords()}})}
function wireAccounting(){const buttons=[...document.querySelectorAll("[data-accounting-period]")];const activate=button=>{buttons.forEach(x=>x.classList.toggle("active",x===button));state.set("accounting-summary-period",buttons.indexOf(button));one("#accountingPeriodLabel").textContent=button.dataset.label;one("#accountingInventory").textContent=money(Number(button.dataset.inventory));one("#accountingSales").textContent=money(Number(button.dataset.sales));one("#accountingProfit").textContent=money(Number(button.dataset.profit));one("#accountingProducts").textContent=button.dataset.products+" "+tr("products sold");one("#accountingReturns").textContent=button.dataset.returns+" "+tr("returns");const chart=one("#accountingMainTrend");chart.dataset.points=button.dataset.points;chart.dataset.color=button.classList.contains("trend-card")?"#b76635":"#2b6b5c";drawSparklines()};buttons.forEach(button=>button.addEventListener("click",()=>activate(button)));activate(buttons[Math.min(Number(state.get("accounting-summary-period",0))||0,buttons.length-1)]||buttons[0])}

