partyForm?.addEventListener("submit",event=>{event.preventDefault();const prefix=partyType.value==="provider"?"pro":"cli",key=prefix+"-sequence";state.set(key,Number(state.get(key,0)||0)+1);partyRecords.push({number:partyNumber.value,name:one("#partyName").value.trim(),type:partyType.value,cycle:one("#billingCycle").selectedOptions[0].text,tax:Number(one("#partyTaxRate").value)||0,amount:Number(one("#openingAmount").value)||0});savePartyRecords();renderPartyRecords();one("#partyFormBody").hidden=true;one("#partySuccess").hidden=false;one("#partySuccessText").textContent=partyNumber.value+" · "+tr("The account is ready for contracts, invoices, bills, and due-date alerts.");});
