if(initialView&&businessViews.has(initialView))selectView(initialView);else clearDashboardView();
window.addEventListener("hashchange",()=>{const requested=location.hash.slice(1).toLowerCase();const view=[...businessViews].find(item=>item.toLowerCase()===requested);if(view&&view!==activeView)selectView(view)});
window.addEventListener("marxia:state",event=>{if(!event.detail.external)return;if(event.detail.name==="theme"){activeTheme=state.validChoice("theme",["light","dark"],"light");applyTheme()}if(event.detail.name==="language"){activeLanguage=state.validChoice("language",["en","es"],"en");applyLanguage();if(activeView)renderDashboardView(activeView)}});




